"""Canonical topology and exact demand prediction for the replay model."""


class NetworkTopology:
    def __init__(self, topology):
        nodes = {node['id']: node for node in topology['nodes']}
        self.names = {i: node['name'] for i, node in nodes.items()}
        self.ids = {name: i for i, name in self.names.items()}
        self.external = tuple(sorted(self.ids[name] for name in topology['external_nodes']))
        self.demand_pairs = tuple((a, b) for a in self.external for b in self.external if a != b)
        self.demand_index = {pair: i for i, pair in enumerate(self.demand_pairs)}

        capacities = {}
        physical = []
        for link in topology['links']:
            a, b, cap = link['source'], link['target'], link['capacity']
            capacities[a, b] = capacities[b, a] = cap
            physical.append((min(a, b), max(a, b), cap))
        for r in self.external:
            capacities[-1, r] = capacities[r, -1] = nodes[r]['external_capacity']
        self.flows = tuple(sorted(capacities))
        self.flow_index = {pair: i for i, pair in enumerate(self.flows)}
        self.capacities = tuple(capacities[pair] for pair in self.flows)
        self.signature = (
            tuple((i, self.names[i], nodes[i]['external_capacity'] if i in self.external else None)
                  for i in sorted(nodes)),
            tuple(sorted(physical)), self.external,
        )

        # A report's index identifies only its measured value, not annotations.
        # Within each flow, the source report precedes the destination report.
        keys = []
        flow_reports = []
        flow_keys = []
        counter_index = {}
        counter_capacity = []
        for i, (a, b) in enumerate(self.flows):
            if a == -1:
                names = (f'low_{self.names[b]}_origination',)
            elif b == -1:
                names = (f'low_{self.names[a]}_termination',)
            else:
                names = (f'low_{self.names[a]}_egress_to_{self.names[b]}',
                         f'low_{self.names[b]}_ingress_from_{self.names[a]}')
            reports = []
            for name in names:
                counter_index[name] = len(keys)
                reports.append(len(keys))
                keys.append(name)
                counter_capacity.append(self.capacities[i])
            flow_reports.append(tuple(reports))
            flow_keys.append(names)
        self.counter_keys = tuple(keys)
        self.counter_index = counter_index
        self.counter_capacity = tuple(counter_capacity)
        self.flow_reports = tuple(flow_reports)
        self.flow_keys = tuple(flow_keys)

        # Each real endpoint has its own independent scenario set.  Sign is
        # positive for incoming traffic and negative for outgoing traffic.
        self.routers = tuple(sorted(nodes))
        router_index = {r: i for i, r in enumerate(self.routers)}
        incident = [[] for _ in self.routers]
        endpoints = []
        for f, (a, b) in enumerate(self.flows):
            ends = []
            for r, sign in ((a, -1), (b, 1)):
                if r == -1:
                    continue
                ri = router_index[r]
                local = len(incident[ri])
                incident[ri].append((f, sign, len(ends)))
                ends.append((ri, local))
            endpoints.append(tuple(ends))
        self.incident = tuple(tuple(items) for items in incident)
        self.endpoints = tuple(endpoints)

    def normalize_routes(self, paths):
        """Preserve the multiset of weighted paths, including repetitions.

        A tuple is both an immutable route plan and a semantic cache identity.
        Object order, bundle order, labels and physical endpoint order vanish.
        """
        if paths is None:
            return None
        bundles = []
        for a, b in self.demand_pairs:
            entries = paths[self.names[a]][self.names[b]]
            bundle = tuple(sorted((tuple(self.ids[name] for name in entry['path']),
                                   entry['weight']) for entry in entries))
            bundles.append(bundle)
        return tuple(bundles)

    def compile_routes(self, routes):
        if routes is None:
            return None
        return tuple(tuple((tuple(self.flow_index[a, b] for a, b in zip(path, path[1:])), weight)
                           for path, weight in bundle) for bundle in routes)

    def predict(self, demands, compiled_routes):
        """Unclamped expectations; null routes omit only internal expectations."""
        if compiled_routes is None:
            result = [None] * len(self.flows)
        else:
            result = [0] * len(self.flows)
            for demand, bundle in zip(demands, compiled_routes):
                if demand:
                    for hops, weight in bundle:
                        contribution = demand * weight
                        for f in hops:
                            result[f] += contribution
            # Aggregate *all* weighted contributions before flooring.
            result = [value // 1000 for value in result]
        for r in self.external:
            result[self.flow_index[-1, r]] = 0
            result[self.flow_index[r, -1]] = 0
        for (a, b), demand in zip(self.demand_pairs, demands):
            result[self.flow_index[-1, a]] += demand
            result[self.flow_index[b, -1]] += demand
        return tuple(result)
