"""Validation of a frozen certificate against current, unclamped demands."""


class Validator:
    def __init__(self, topology, settings):
        self.topology = topology
        self.trials = settings['trials']
        self.cutoff = tuple(settings['cutoff'])
        self.bias = settings['bias']
        self.tau = settings['tau']
        self.gamma = tuple(settings['gamma'])

    def validate(self, certificate, prediction, snapshot_id):
        checked = passed = 0
        failed = []
        cutoff_n, cutoff_d = self.cutoff
        for f, expected in enumerate(prediction):
            if expected is None or certificate.supports[f] * cutoff_d < cutoff_n * self.trials:
                continue
            keys = self.topology.flow_keys[f]
            checked += len(keys)
            x = certificate.values[f] * 1_000_000
            y = expected * (1_000_000 - self.bias)
            if 1_000_000 * abs(x - y) <= self.tau * max(x, y):
                passed += len(keys)
            else:
                failed.extend(keys)
        gamma_n, gamma_d = self.gamma
        consistent = None if not checked else passed * gamma_d >= gamma_n * checked
        return {'op': 'validate', 'id': snapshot_id, 'checked': checked, 'passed': passed,
                'consistent': consistent, 'failed': sorted(failed)}
