#!/usr/bin/env python3
"""One JSON request to EOF, one replay result, and no runtime file writes."""
import json
import math
import sys
from crosscheck import CrossCheck


def pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError('duplicate key')
        result[key] = value
    return result


def finite(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError('nonfinite number')
    return result


def reject_constant(value):
    raise ValueError('nonfinite constant')


def main():
    try:
        request = json.loads(sys.stdin.buffer.read().decode('utf-8'), object_pairs_hook=pairs,
                             parse_float=finite, parse_constant=reject_constant)
    except (ValueError, UnicodeError):
        sys.stdout.write('{"error":"invalid_json"}\n')
        return
    results = []
    for stream in request['streams']:
        engine = CrossCheck(stream['topology'])
        results.append({'events': engine.replay(stream['events'], stream['settings'])})
    sys.stdout.write(json.dumps({'streams': results}, separators=(',', ':'), allow_nan=False) + '\n')


if __name__ == '__main__':
    main()
